package io.baozhu.copilot.common; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; @RestControllerAdvice public class GlobalExceptionHandler {@ExceptionHandler(MethodArgumentNotValidException.class) public ResponseEntity<ApiError> invalid(MethodArgumentNotValidException e,HttpServletRequest r){return response(HttpStatus.BAD_REQUEST,e.getBindingResult().getFieldErrors().stream().findFirst().map(x->x.getField()+": "+x.getDefaultMessage()).orElse("Invalid request"),r);} @ExceptionHandler(IllegalStateException.class) public ResponseEntity<ApiError> state(IllegalStateException e,HttpServletRequest r){return response(HttpStatus.BAD_GATEWAY,e.getMessage(),r);} private ResponseEntity<ApiError> response(HttpStatus s,String m,HttpServletRequest r){return ResponseEntity.status(s).body(new ApiError(java.time.Instant.now(),s.value(),s.getReasonPhrase(),m,r.getRequestURI()));}}